package generation

// The user-management surface's generated files (users.go).
const (
	// usersTemplate emits the application's user-management handlers as delegations to
	// the library over the surface the application supplies for each Auth.
	usersTemplate = `// Code generated by resourcegeneration. DO NOT EDIT.
// Source: {{ .Source }}

package {{ .Package }}

import (
	"net/http"

	{{ .LocalPackageImports }}
	"github.com/cccteam/ccc/resource"
)
{{ range $s := .Surfaces }}
// The {{ $s.Auth }} auth's user-management surface ({{ $s.ImportPath }}): the application
// supplies it through {{ $s.Accessor }}, built with {{ $.RouterPackage }}.New{{ $s.Accessor }} over the
// auth's stores, and the handlers below delegate to it.
var _ interface {
	{{ $s.Accessor }}() *resource.UserSurface[{{ $.RouterPackage }}.{{ $s.TypeName }}]
} = (*{{ $.ApplicationName }})(nil)
{{ range $h := $s.Handlers }}
// {{ $h.Name }} {{ $h.Comment }}.
func ({{ $.ReceiverName }} *{{ $.ApplicationName }}) {{ $h.Name }}() http.HandlerFunc {
	return {{ $.ReceiverName }}.{{ $s.Accessor }}().{{ $h.Method }}({{ $.ReceiverName }}, {{ $.RouterPackage }}.Collection())
}
{{ end }}
{{- end }}`

	// userSurfacesTemplate emits the router package's marker type and constructor per
	// Auth: the declaration the generator derived from the Auth's methods, fixed in a
	// type the surface, its rows and its handlers are instantiated with.
	userSurfacesTemplate = `// Code generated by resourcegeneration. DO NOT EDIT.
// Source: {{ .Source }}

package {{ .Package }}

import (
	"github.com/cccteam/ccc/resource"
)
{{ range $s := .Surfaces }}
// {{ $s.TypeName }} marks the {{ $s.PackageName }} auth ({{ $s.ImportPath }}) for the user-management
// surface the library serves on the {{ $s.OutletList }}: {{ $s.ResourceList }}.
// The surface, its rows and its handlers are instantiated with it, so the auth's
// resources are their own Go types carrying these names into the collection.
type {{ $s.TypeName }} struct{}

// UserSurfaceDeclaration is what the generator derived from the auth's sign-in methods.
func ({{ $s.TypeName }}) UserSurfaceDeclaration() resource.UserSurfaceDeclaration {
	return resource.UserSurfaceDeclaration{
		Auth:        "{{ $s.Auth }}",
		Tenant:      "{{ $s.Tenant }}",
		DomainParam: "{{ $s.DomainParam }}",
		Shape: resource.UserSurfaceShape{
			Password: {{ $s.Password }},
			Registrations: []resource.UserRegistration{
				{{- range $r := $s.Registrations }}
				{Name: "{{ $r.Name }}", Kind: "{{ $r.Kind }}", Label: "{{ $r.Label }}", Invited: {{ $r.Invited }}, SyncsRoles: {{ $r.SyncsRoles }}},
				{{- end }}
			},
		},
	}
}

// {{ $s.Constructor }} builds the {{ $s.PackageName }} auth's surface over its stores: the auth's
// users and identities (sessionusers.Accounts over the auth's session API) and its
// engine's user manager, whose memberships are the seats. The application returns the
// surface from {{ $s.Accessor }}(), which the generated handlers call.
func {{ $s.Constructor }}(accounts resource.UserAccounts, seats resource.UserSeats) *resource.UserSurface[{{ $s.TypeName }}] {
	return resource.NewUserSurface[{{ $s.TypeName }}](accounts, seats)
}
{{ end }}`
)
